    <div class="profile-btns">
      <button class="profile-btn" onclick="selectUser('Nyxu')">
        <span class="avatar">🦊</span>Nyxu
      </button>
      <button class="profile-btn" onclick="selectUser('Franco')">
        <span class="avatar">🚀</span>Franco
      </button>
    </div>
  </div>
</div>

<!-- HEADER -->
<header>
  <div class="logo">⚡ <span>FrontierAdvice</span> · n8n Sync</div>
  <div class="header-right">
    <div class="user-badge"><span class="user-dot"></span><span id="user-label">...</span></div>
    <button class="btn-icon" onclick="toggleTheme()" title="Cambiar tema" id="theme-btn">🌙</button>
    <button class="btn-icon" onclick="logout()" title="Cerrar sesión">↩ Salir</button>
    <button class="btn btn primary" onclick="loadDashboard()">↻ Refrescar</button>
  </div>
</header>

<!-- MAIN -->
<main>
  <div class="stats-bar">
    <div class="stat-card green"><div class="label">Sincronizados</div><div class="value" id="cnt-synced">–</div></div>
    <div class="stat-card yellow"><div class="label">Solo en n8n</div><div class="value" id="cnt-n8n">–</div></div>
    <div class="stat-card blue"><div class="label">Solo en GitHub</div><div class="value" id="cnt-gh">–</div></div>
  </div>

  <div id="dashboard-content">
    <div class="loader"><span class="spin">⟳</span> Cargando workflows...</div>
  </div>
</main>

<!-- COMMITS MODAL -->
<div class="modal-bg" id="modal-commits">
  <div class="modal">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
      <h2 id="modal-title">Historial de commits</h2>
      <button class="btn" onclick="closeModal()">✕ Cerrar</button>
    </div>
    <div id="modal-body"></div>
  </div>
</div>

<div id="toast"></div>

<script>
const WEBHOOK = '${WEBHOOK_URL}';
let currentUser = '';

// ── THEME ──
function applyTheme(t) {
  document.documentElement.setAttribute('data-theme', t);
  document.getElementById('theme-btn').textContent = t === 'dark' ? '🌙' : '☀️';
}
function toggleTheme() {
  const t = document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
  localStorage.setItem('fa_theme', t); applyTheme(t);
}
(function() { applyTheme(localStorage.getItem('fa_theme') || 'dark'); })();

// ── SESSION ──
function selectUser(name) {
  sessionStorage.setItem('n8n_user', name);
  currentUser = name;
  document.getElementById('overlay').style.display = 'none';
  document.getElementById('user-label').textContent = '👤 ' + name;
  loadDashboard();
}
function logout() {
  sessionStorage.removeItem('n8n_user'); location.reload();
}
(function checkSession() {
  const u = sessionStorage.getItem('n8n_user');
  if (u) { currentUser = u; document.getElementById('overlay').style.display = 'none'; document.getElementById('user-label').textContent = '👤 ' + u; loadDashboard(); }
})();

// ── TOAST ──
function toast(msg, ok=true) {
  const el = document.getElementById('toast');
  el.textContent = (ok ? '✅ ' : '❌ ') + msg;
  el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 3000);
}

// ── API ──
async function api(params) {
  const url = WEBHOOK + '?' + new URLSearchParams({ ...params, user: currentUser }).toString();
  const r = await fetch(url); if (!r.ok) throw new Error('HTTP ' + r.status);
  return r.json();
}

// ── DASHBOARD ──
async function loadDashboard() {
  document.getElementById('dashboard-content').innerHTML = '<div class="loader"><span class="spin">⟳</span> Cargando...</div>';
  try {
    const data = await api({ action: 'fetchAllWorkflows' });
    const synced = data.synced || []; const n8nOnly = data.n8nOnly || []; const ghOnly = data.githubOnly || [];
    document.getElementById('cnt-synced').textContent = synced.length;
    document.getElementById('cnt-n8n').textContent = n8nOnly.length;
    document.getElementById('cnt-gh').textContent = ghOnly.length;
    let html = '';
    if (synced.length) html += renderSection('✅ Sincronizados con GitHub', synced, 'synced', 'var(--green)', 'badge-green');
    if (n8nOnly.length) html += renderSection('⚠️ Solo en n8n (pendientes de sync)', n8nOnly, 'n8nOnly', 'var(--yellow)', 'badge-yellow');
    if (ghOnly.length) html += renderSection('📦 Solo en GitHub', ghOnly, 'ghOnly', 'var(--accent)', 'badge-blue');
    if (!html) html = '<div class="empty">No se encontraron workflows.</div>';
    document.getElementById('dashboard-content').innerHTML = html;
  } catch(e) { document.getElementById('dashboard-content').innerHTML = '<div class="empty">❌ Error: ' + e.message + '</div>'; }
}

function renderSection(title, items, type, color, badgeClass) {
  let rows = items.map(wf => renderRow(wf, type)).join('');
  return \`<div class="section-header"><div class="section-title" style="color:\${color}">${title} <span class="badge \${badgeClass}">\${items.length}</span></div></div><div class="wf-list">\${rows}</div>\`;
}

function renderRow(wf, type) {
  const active = wf.active;
  const dot = type === 'synced' ? 'var(--green)' : type === 'n8nOnly' ? 'var(--yellow)' : 'var(--accent)';
  const ghLink = wf.wf_url ? \`<a class="github-link" href="\${wf.wf_url}" target="_blank">↗ GitHub</a>\` : '';
  const toggleHtml = wf.wf_id ? \`<label class="toggle-switch" title="Activar/Desactivar"><input type="checkbox" \${active?'checked':''} onchange="toggleWf('\${wf.wf_id}',this.checked)"><span class="slider"></span></label>\` : '';
  const syncBtn = (type === 'n8nOnly' || type === 'synced') && wf.wf_id ? \`<button class="btn primary" onclick="syncWf('\${wf.wf_id}','\${escapePath(wf.path)}','\${escapeStr(wf.name)}')" title="Guardar en GitHub">⬆ Sync</button>\` : '';
  const commitsBtn = wf.path ? \`<button class="btn" onclick="viewCommits('\${escapePath(wf.path)}','\${wf.wf_id}','\${escapeStr(wf.name)}')" title="Ver historial">🕓 Commits</button>\` : '';
  const importBtn = type === 'ghOnly' ? \`<button class="btn" onclick="importWf('\${escapePath(wf.path)}','\${wf.wf_id}','\${escapeStr(wf.name)}')">⬇ Importar</button>\` : '';
  return \`<div class="wf-row"><div class="wf-status-dot" style="background:\${dot}"></div><div class="wf-info"><div class="wf-name">\${wf.name || wf.wf_id}</div><div class="wf-meta">ID: \${wf.wf_id || '—'} \${ghLink}</div></div><div class="wf-actions">\${toggleHtml}\${syncBtn}\${commitsBtn}\${importBtn}</div></div>\`;
}

function escapePath(p) { return Array.isArray(p) ? (p[0]||'').replace(/'/g,"\\'"): (p||'').replace(/'/g,"\\'"); }
function escapeStr(s) { return (s||'').replace(/'/g,"\\'"); }

async function toggleWf(id, active) {
  try {
    await api({ action: 'toggleStatus', workflowId: id, active: String(active) });
    toast(active ? 'Workflow activado' : 'Workflow desactivado');
  } catch(e) { toast('Error al cambiar estado', false); }
}

async function syncWf(id, path, name) {
  const msg = prompt('Mensaje del commit (opcional):', \`[n8n Sync] \${name} - Actualizado por \${currentUser}\`);
  if (msg === null) return;
  try {
    toast('Sincronizando...');
    await api({ action: 'syncWorkflow', workflowId: id, path: JSON.stringify([path]), commitMessage: msg || '' });
    toast('Guardado en GitHub ✓'); loadDashboard();
  } catch(e) { toast('Error al sincronizar', false); }
}

async function viewCommits(path, id, name) {
  document.getElementById('modal-title').textContent = '🕓 Commits — ' + name;
  document.getElementById('modal-body').innerHTML = '<div class="loader"><span class="spin">⟳</span> Cargando...</div>';
  document.getElementById('modal-commits').classList.add('open');
  try {
    const data = await api({ action: 'fetchCommits', workflowId: id, path: JSON.stringify([path]) });
    const commits = Array.isArray(data) ? data : [];
    if (!commits.length) { document.getElementById('modal-body').innerHTML = '<div class="empty">Sin commits registrados.</div>'; return; }
    document.getElementById('modal-body').innerHTML = commits.map(c => \`<div class="commit-item"><div class="commit-msg">\${c.message}</div><div class="commit-meta">👤 \${c.committer} · 🕓 \${new Date(c.timestamp).toLocaleString('es')} · <a class="github-link" href="\${c.url}" target="_blank">Ver commit ↗</a></div>\${c.sha ? \`<button class="btn" style="margin-top:8px" onclick="restoreWf('\${escapePath(path)}','\${id}','\${c.sha}')">⏪ Restaurar esta versión</button>\` : ''}</div>\`).join('');
  } catch(e) { document.getElementById('modal-body').innerHTML = '<div class="empty">Error: ' + e.message + '</div>'; }
}

async function restoreWf(path, id, sha) {
  const action = confirm('¿Restaurar esta versión? Elige:\nAceptar = Reemplazar workflow existente\nCancelar = Crear workflow nuevo') ? 'replace' : 'import_new';
  closeModal();
  try {
    toast('Restaurando...');
    await api({ action: 'importWorkflow', workflowId: id, path: JSON.stringify([path]), sha, importAction: action });
    toast('Workflow restaurado ✓'); loadDashboard();
  } catch(e) { toast('Error al restaurar', false); }
}

async function importWf(path, id, name) {
  if (!confirm('¿Importar "' + name + '" desde GitHub?')) return;
  try {
    toast('Importando...');
    await api({ action: 'importWorkflow', workflowId: id, path: JSON.stringify([path]), sha: '', importAction: 'import_new' });
    toast('Importado ✓'); loadDashboard();
  } catch(e) { toast('Error al importar', false); }
